@Test
public void rewrite() throws Exception {
    setupGadget(getGadgetXml(CONTENT));
    Capture<PipelinedData.Batch> batchCapture = new Capture<PipelinedData.Batch>();
    // Dummy return results (the "real" return would have two values)
    Callable<PreloadedData> callable = createPreloadTask("key", "{data: {foo: 'bar'}}");
    // One batch with 1 each HTTP and Social preload
    expect(preloader.createPreloadTasks(same(gadget.getContext()), and(eqBatch(1, 1), capture(batchCapture)))).andReturn(ImmutableList.of(callable));
    control.replay();
    rewriter.rewrite(gadget, content);
    // Verify the data set is injected, and the os-data was deleted
    assertTrue("Script not inserted", content.getContent().contains("DataContext.putDataSet(\"key\",{\"foo\":\"bar\"})"));
    assertFalse("os-data wasn't deleted", content.getContent().contains("type=\"text/os-data\""));
    assertTrue(batchCapture.getValue().getSocialPreloads().containsKey("me"));
    assertTrue(batchCapture.getValue().getHttpPreloads().containsKey("json"));
    assertEquals(ImmutableSet.of("opensocial-data"), gadget.getRemovedFeatures());
    assertEquals(ImmutableSet.of("opensocial-data-context"), gadget.getAddedFeatures());
    control.verify();
}

@Test
public void rewriteWithTwoBatches() throws Exception {
    setupGadget(getGadgetXml(TWO_BATCH_CONTENT));
    gadget.setContext(new GadgetContext() {

        @Override
        public String getParameter(String property) {
            // Provide the filename to be requested in the first batch
            if ("view-params".equals(property)) {
                return "{'file': 'test.json'}";
            }
            return null;
        }
    });
    // First batch, the HTTP fetch
    Capture<PipelinedData.Batch> firstBatch = new Capture<PipelinedData.Batch>();
    Callable<PreloadedData> firstTask = createPreloadTask("json", "{data: {user: 'canonical'}}");
    // Second batch, the user fetch
    Capture<PipelinedData.Batch> secondBatch = new Capture<PipelinedData.Batch>();
    Callable<PreloadedData> secondTask = createPreloadTask("me", "{data: {'id':'canonical'}}");
    // First, a batch with an HTTP request
    expect(preloader.createPreloadTasks(same(gadget.getContext()), and(eqBatch(0, 1), capture(firstBatch)))).andReturn(ImmutableList.of(firstTask));
    // Second, a batch with a social request
    expect(preloader.createPreloadTasks(same(gadget.getContext()), and(eqBatch(1, 0), capture(secondBatch)))).andReturn(ImmutableList.of(secondTask));
    control.replay();
    rewriter.rewrite(gadget, content);
    control.verify();
    // Verify the data set is injected, and the os-data was deleted
    assertTrue("First batch not inserted", content.getContent().contains("DataContext.putDataSet(\"json\",{\"user\":\"canonical\"})"));
    assertTrue("Second batch not inserted", content.getContent().contains("DataContext.putDataSet(\"me\",{\"id\":\"canonical\"})"));
    assertFalse("os-data wasn't deleted", content.getContent().contains("type=\"text/os-data\""));
    // Check the evaluated HTTP request
    RequestAuthenticationInfo request = firstBatch.getValue().getHttpPreloads().get("json");
    assertEquals("http://example.org/test.json", request.getHref().toString());
    // Check the evaluated person request
    JSONObject personRequest = (JSONObject) secondBatch.getValue().getSocialPreloads().get("me");
    assertEquals("canonical", personRequest.getJSONObject("params").getJSONArray("userId").get(0));
    assertEquals(ImmutableSet.of("opensocial-data"), gadget.getRemovedFeatures());
    assertEquals(ImmutableSet.of("opensocial-data-context"), gadget.getAddedFeatures());
}

@Test
public void rewriteWithBlockedBatch() throws Exception {
    setupGadget(getGadgetXml(BLOCKED_FIRST_BATCH_CONTENT));
    // Expect a batch with no content
    expect(preloader.createPreloadTasks(same(gadget.getContext()), eqBatch(0, 0))).andReturn(ImmutableList.<Callable<PreloadedData>>of());
    control.replay();
    rewriter.rewrite(gadget, content);
    control.verify();
    // Check there is no DataContext inserted
    assertFalse("DataContext write shouldn't be present", content.getContent().indexOf("DataContext.putDataSet(") > 0);
    // And the os-data elements should be present
    assertTrue("os-data was deleted", content.getContent().indexOf("type=\"text/os-data\"") > 0);
    assertEquals(ImmutableSet.<String>of(), gadget.getRemovedFeatures());
    assertEquals(ImmutableSet.<String>of(), gadget.getAddedFeatures());
}

